const input = $input.first().json;
const body = input.body || input;

const limpar = (valor, limite = 500) => valor ? String(valor).trim().slice(0, limite) : '';

const payload = {
  id_agendamento: limpar(body.id_agendamento || `MRJ-${Date.now()}`, 40),
  nome_cliente: limpar(body.nome_cliente || body.name || body.nome, 200),
  telefone: limpar(body.telefone || body.phone || body.whatsapp, 40),
  whatsapp: limpar(body.whatsapp, 40),
  email: limpar(body.email, 180),
  telegram: limpar(body.telegram, 120),
  servico: limpar(body.servico || body.service, 180),
  duracao_media: Number(body.duracao_media || body.duration || 50),
  valor_referencia: body.valor_referencia || body.price || null,
  data_agendada: limpar(body.data_agendada || body.date, 20),
  hora_agendada: limpar(body.hora_agendada || body.time, 20),
  local: limpar(body.local || body.location, 220),
  observacoes_cliente: limpar(body.observacoes_cliente || body.notes, 1000),
  status: 'Pendente',
  origem: 'site_massoterapiarj',
  recebido_em: new Date().toISOString()
};

const erros = [];
if (!payload.nome_cliente) erros.push('Nome do cliente é obrigatório.');
if (!payload.servico) erros.push('Serviço é obrigatório.');
if (!payload.data_agendada) erros.push('Data é obrigatória.');
if (!payload.hora_agendada) erros.push('Horário é obrigatório.');
if (!payload.whatsapp && !payload.telefone && !payload.email && !payload.telegram) erros.push('Informe ao menos um contato.');

if (erros.length) {
  throw new Error(`VALIDACAO: ${erros.join(' ')}`);
}

return [{ json: payload }];
